import { type HTMLAttributes } from 'react';

function cn(...classes: (string | false | undefined | null)[]) {
  return classes.filter(Boolean).join(' ');
}

export type SkeletonProps = {
  variant?: 'default' | 'circle' | 'text';
  className?: string;
} & HTMLAttributes<HTMLDivElement>;

export function Skeleton({ variant = 'default', className, ...props }: SkeletonProps) {
  return (
    <div
      aria-hidden="true"
      className={cn(
        'skeleton',
        variant !== 'default' && `skeleton--${variant}`,
        className,
      )}
      {...props}
    />
  );
}

/* -------------------------------------------------------------------------
   Skeleton

   Loading placeholder. Pulse animation on muted background.
   Consumer sets width/height/border-radius via style or className.

   Parts: .skeleton
   ------------------------------------------------------------------------- */

.skeleton {
  display: block;
  background-color: var(--border);
  border-radius: var(--radius-md);
  animation: skeleton-pulse var(--duration-1000) var(--easing-in-out) infinite;
}

@keyframes skeleton-pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: var(--opacity-50); }
}

/* ---- Shape helpers ---- */

.skeleton--circle {
  border-radius: var(--radius-full);
}

.skeleton--text {
  height: 1em;
  border-radius: var(--radius-sm);
}

/* ---- Reduced motion ---- */

@media (prefers-reduced-motion: reduce) {
  .skeleton {
    animation: none;
  }
}

